using FastEndpoints; using Mediator; using Microsoft.AspNetCore.Identity; using Nimble.Modulith.Email.Contracts; using Nimble.Modulith.Users.Infrastructure;
namespace Nimble.Modulith.Users.Endpoints;
public record RegisterRequest(string Email,string Password); public record AuthResponse(bool Success,string Message,string? UserId=null,IEnumerable<string>? Errors=null);
public class Register(UserManager<IdentityUser> users):Endpoint<RegisterRequest,AuthResponse>{ public override void Configure(){Post("/register");AllowAnonymous();Summary(s=>s.Summary="Register a new user");} public override async Task HandleAsync(RegisterRequest r,CancellationToken ct){ var user=new IdentityUser{UserName=r.Email,Email=r.Email,EmailConfirmed=true}; var res=await users.CreateAsync(user,r.Password); if(res.Succeeded){ await users.AddToRoleAsync(user,"User"); await Send.OkAsync(new(true,"User registered",user.Id),ct);} else await Send.OkAsync(new(false,"Registration failed",null,res.Errors.Select(e=>e.Description)),ct);} }
public record LoginRequest(string Email,string Password); public class Login(SignInManager<IdentityUser> signIn):Endpoint<LoginRequest,AuthResponse>{ public override void Configure(){Post("/login");AllowAnonymous();} public override async Task HandleAsync(LoginRequest r,CancellationToken ct){ var result=await signIn.PasswordSignInAsync(r.Email,r.Password,false,false); await Send.OkAsync(result.Succeeded?new(true,"Login successful"):new(false,"Invalid credentials"),ct);} }
public record AddRoleRequest(string Id,string Role); public class AddRoleToUser(UserManager<IdentityUser> users):Endpoint<AddRoleRequest,AuthResponse>{ public override void Configure(){Post("/users/{id}/roles");Roles("Admin");} public override async Task HandleAsync(AddRoleRequest r,CancellationToken ct){ var user=await users.FindByIdAsync(r.Id); if(user is null){ await Send.NotFoundAsync(ct); return;} var res=await users.AddToRoleAsync(user,r.Role); await Send.OkAsync(new(res.Succeeded,res.Succeeded?"Role added":"Role failed",user.Id,res.Errors.Select(e=>e.Description)),ct);} }
public record ResetPasswordRequest(string Email); public record ResetPasswordResponse(bool Success,string Message);
public class ResetPassword(UserManager<IdentityUser> users,IMediator mediator):Endpoint<ResetPasswordRequest,ResetPasswordResponse>{ public override void Configure(){Post("/users/reset-password");AllowAnonymous();} public override async Task HandleAsync(ResetPasswordRequest r,CancellationToken ct){ var user=await users.FindByEmailAsync(r.Email); if(user is not null){ var pass=PasswordGenerator.GeneratePassword(); if(await users.HasPasswordAsync(user)) await users.RemovePasswordAsync(user); await users.AddPasswordAsync(user,pass); await mediator.Send(new SendEmailCommand(user.Email!,"Password Reset - Temporary Password",$"Your new temporary password is: {pass}"),ct);} await Send.OkAsync(new(true,"If the email exists in our system, a password reset email has been sent."),ct);} }
